html[lang="it"] body.homepage-page .lt-resourceShelf .lt-sectionHeader {
  grid-template-columns: minmax(0, 1fr);
  gap: 0.75rem;
  align-items: start;
  text-align: left;
}
html[lang="it"] body.homepage-page .lt-resourceShelf .lt-sectionHeader h2 {
  max-width: none;
}

